def test_unreachable_source_usable(self):
    """不可达来源节点的选项文字仍可修改。"""
    data = self.load_sample_data()
    data["nodes"].append(
        {"id": "side", "text": "旁路入口", "options": [
            {"text": "自环", "target": "side"}]}
    )
    path = self.make_sample(data)
    result = self.run_and_assert_set_text(path, "side", 1, "绕一圈", {
        "start": "start",
        "nodes": [
            {"id": "start", "text": "你来到岔路口。", "options": [
                {"text": "向左走", "target": "forest"},
                {"text": "向右走", "target": "river"},
            ]},
            {"id": "forest", "text": "你到了森林。", "options": []},
            {"id": "river", "text": "你到了河边。", "options": []},
            {"id": "side", "text": "旁路入口", "options": [
                {"text": "绕一圈", "target": "side"}]},
        ],
    })
    parsed = json.loads(result.stdout[:-1])
    # 从 start 做可达性展开：side 仍不可达，target 仍指向自身。
    by_id = {n["id"]: n for n in parsed["nodes"]}
    seen = {parsed["start"]}
    pending = [parsed["start"]]
    while pending:
        for option in by_id[pending.pop()]["options"]:
            if option["target"] not in seen:
                seen.add(option["target"])
                pending.append(option["target"])
    self.assertNotIn("side", seen)
    self.assertEqual(parsed["nodes"][3]["options"][0]["target"], "side")

def test_self_reference_and_cycle_unaffected(self):
    """自引用与合法循环中的选项可改文字，命令正常结束，target 不变。"""
    data = {
        "start": "a",
        "nodes": [
            {"id": "a", "text": "甲", "options": [
                {"text": "去 b", "target": "b"}],
            },
            {"id": "b", "text": "乙", "options": [
                {"text": "去 a", "target": "a"}],
            },
        ],
    }
    path = self.make_sample(data)
    self.run_and_assert_set_text(path, "a", 1, "走向 b", {
        "start": "a",
        "nodes": [
            {"id": "a", "text": "甲", "options": [
                {"text": "走向 b", "target": "b"}],
            },
            {"id": "b", "text": "乙", "options": [
                {"text": "去 a", "target": "a"}],
            },
        ],
    })

