    path = self.make_sample(data)
    result = self.run_and_assert_set_text(path, "start", 2, "  \t ", {
        "start": "start",
        "nodes": [
            {"id": "start", "text": "你来到岔路口。", "options": [
                {"text": "向左走", "target": "forest"},
                {"text": "  \t ", "target": "river"},
            ]},
            {"id": "forest", "text": "你到了森林。", "options": []},
            {"id": "river", "text": "你到了河边。", "options": []},
        ],
    })
